from itertools import permutations
def cands(g):
    H=len(g);W=len(g[0])
    C={(i,j) for i in range(H) for j in range(W) if g[i][j]==8}
    out={}
    MISS={(0,0):2,(1,0):3,(0,1):4,(1,1):1}
    for i in range(H):
        for j in range(W):
            if (i,j) not in C: continue
            cs=[]
            for a in (i-1,i):
                for b in (j-1,j):
                    if not(0<=a<H-1 and 0<=b<W-1): continue
                    blk=[(a+x,b+y) for x in range(2) for y in range(2)]
                    pre=[c for c in blk if c in C]
                    if len(pre)==4: cs.append(1)
                    elif len(pre)==3:
                        miss=[c for c in blk if c not in C][0]
                        cs.append(MISS[(miss[0]-a,miss[1]-b)])
            out[(i,j)]=cs
    return out
